typedef struct Vector {float x,y,z;} Vector;typedef struct Screen {float x,y;} Screen;typedef struct View {char unknown0[60];Vector position;} View;typedef struct Camera {char unknown0[40];Vector right;} Camera;
typedef char check_vector[sizeof(Vector)==12&&sizeof(Screen)==8?1:-1];typedef char check_position[(unsigned long)&((View *)0)->position==60?1:-1];typedef char check_camera[(unsigned long)&((Camera *)0)->right==40?1:-1];extern Camera camera;extern void transform_at(int,Vector *,Vector *),project_at(int,Vector *,Screen *);extern float length_at(Vector *);
int grid_view_visible(View *o,float distance,float radius) {Vector position;Screen screen;transform_at(0,&o->position,&position);if(position.z+radius/2.0f<0.0f) return 0;if(length_at(&position)>distance) return 0;if(position.x<0.0f) {position.x=camera.right.x*radius+o->position.x;position.y=camera.right.y*radius+o->position.y;position.z=camera.right.z*radius+o->position.z;project_at(0,&position,&screen);if(screen.x<0.0f) return 0;}else {position.x=o->position.x-camera.right.x*radius;position.y=o->position.y-camera.right.y*radius;position.z=o->position.z-camera.right.z*radius;project_at(0,&position,&screen);if(screen.x>640.0f) return 0;}return 1;}
